e']?'checked':''?>></td><td><input class="form-check-input" type="checkbox" name="scenarios[<?=$i?>][is_required]" <?=$s['is_required']?'checked':''?>></td><td><button class="btn btn-sm btn-outline-danger remove-scenario" type="button"><i class="bi bi-trash"></i></button></td></tr><?php endforeach?></tbody></table></div>
