<script>
document.addEventListener('DOMContentLoaded',()=>{
 const form=document.getElementById('automaticDesignForm'),indicator=document.getElementById('unsavedIndicator');form?.addEventListener('input',()=>indicator.innerHTML='<i class="bi bi-exclamation-circle"></i> Ada perubahan belum disimpan');
 document.getElementById('catalogPicker')?.addEventListener('change',e=>{const row=e.target.selectedOptions[0]?.dataset.row?JSON.parse(e.target.selectedOptions[0].dataset.row):{};['material','dn_mm','outside_diameter_mm','wall_thickness_mm','inside_diameter_mm','pressure_class','allowable_pressure_bar','hazen_williams_c','darcy_roughness_mm','price_per_meter','description'].forEach(key=>{const field=document.querySelector('#catalogForm [name="'+key+'"]');if(field)field.value=row[key]??'';});});
 const updateWeights=()=>{const total=[...document.querySelectorAll('.weight-input')].reduce((s,x)=>s+(parseFloat(x.value)||0),0),el=document.getElementById('weightTotal');if(el){el.textContent='Jumlah bobot: '+total.toFixed(1)+'%';el.className=Math.abs(total-100)<.01?'text-success':'text-danger';}};document.querySelectorAll('.weight-input').forEach(x=>x.addEventListener('input',updateWeights));updateWeights();
 let nextScenario=document.querySelectorAll('#scenarioTable tbody tr').length;document.getElementById('addScenario')?.addEventListener('click',()=>{const i=nextScenario++,tr=document.createElement('tr');tr.innerHTML=`<td><input class="form-control form-control-sm" name="scenarios[${i}][code]" value="CUSTOM-${i+1}"></td><td><input class="form-control form-control-sm" name="scenarios[${i}][name]" value="Skenario baru"></td><td><select class="form-select form-select-sm" name="scenarios[${i}][scenario_type]"><option>CUSTOM</option><option>FIRE</option><option>OUTAGE</option></select></td><td><input class="form-control form-control-sm" type="number" step="any" name="scenarios[${i}][demand_multiplier]" value="1"></td><td><input class="form-control form-control-sm" type="number" step="any" name="scenarios[${i}][source_head_adjustment_m]" value="0"></td><td><input class="form-control form-control-sm" type="number" step="any" name="scenarios[${i}][fire_flow_lps]" value="0"></td><td><input class="form-check-input" type="checkbox" name="scenarios[${i}][is_active]" checked></td><td><input class="form-check-input" type="checkbox" name="scenarios[${i}][is_required]" checked></td><td><button class="btn btn-sm btn-outline-danger remove-scenario" type="button"><i class="bi bi-trash"></i></button></td>`;document.querySelector('#scenarioTable tbody').appendChild(tr);});
 document.addEventListener('click',e=>{if(e.target.closest('.remove-scenario'))e.target.closest('tr').remove();});
 <?php if($alternatives):?>new Chart(document.getElementById('alternativeChart'),{type:'bar',data:{labels:<?=json_encode(array_column($alternatives,'combination_code'))?>,datasets:[{label:'Tekanan minimum (m)',data:<?=json_encode(array_map('floatval',array_column($alternatives,'minimum_pressure_m')))?>,backgroundColor:'#0d6efd'},{label:'Kecepatan maksimum (m/s)',data:<?=json_encode(array_map('floatval',array_column($alternatives,'maximum_velocity_mps')))?>,backgroundColor:'#10b981'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}});<?php endif?>
 <?php if(!empty($selectedNodes)):?>new Chart(document.getElementById('hglChart'),{type:'line',data:{labels:<?=json_encode(array_column($selectedNodes,'node_name'))?>,datasets:[{label:'Hydraulic head (m)',data:<?=json_encode(array_map('floatval',array_column($selectedNodes,'hydraulic_head_m')))?>,borderColor:'#0d6efd'},{label:'Elevasi (m)',data:<?=json_encode(array_map('floatval',array_column($selectedNodes,'elevation_m')))?>,borderColor:'#7950f2'}]},options:{responsive:true,maintainAspectRatio:false}});new Chart(document.getElementById('pressureChart'),{type:'line',data:{labels:<?=json_encode(array_column($selectedNodes,'node_name'))?>,datasets:[{label:'Tekanan node (m)',data:<?=json_encode(array_map('floatval',array_column($selectedNodes,'pressure_m')))?>,borderColor:'#0d6efd',backgroundColor:'#0d6efd22',fill:true}]},options:{responsive:true,maintainAspectRatio:false}});<?php endif?>
